recipes.code:
{
  "inputs": [
    {
      "id": "qase-api-token",
      "type": "promptString",
      "description": "Qase API token from app.qase.io > Settings > API Tokens",
      "password": true
    }
  ],
  "servers": {
    "server": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@qase/mcp-server@2.0.0"
      ],
      "env": {
        "QASE_API_TOKEN": "${input:qase-api-token}",
        "QASE_API_DOMAIN": "api.qase.io"
      }
    }
  }
}
